import vazkii.botania.api.corporea.*;
import vazkii.botania.common.block.block_entity.corporea.CorporeaRetainerBlockEntity;
import vazkii.botania.xplat.XplatAbstractions;

import java.util.*;
import java.util.function.Function;

public class CorporeaHelperImpl implements CorporeaHelper {
	private final WeakHashMap<CorporeaSpark, Set<CorporeaNode>> cachedNetworks = new WeakHashMap<>();

	@Override
	public Set<CorporeaNode> getNodesOnNetwork(CorporeaSpark spark) {
		CorporeaSpark master = spark.getMaster();
		if (master == null) {
			return Collections.emptySet();
		}
		Set<CorporeaSpark> network = master.getConnections();

		var cache = cachedNetworks.get(master);
		if (cache != null) {
			return cache;
		}

		Set<CorporeaNode> nodes = new LinkedHashSet<>();
		if (network != null) {
			for (CorporeaSpark otherSpark : network) {
				if (otherSpark != null) {
					nodes.add(otherSpark.getSparkNode());
				}
			}
		}

		cachedNetworks.put(master, nodes);
		return nodes;
	}

	@Override
	public CorporeaRequestMatcher createMatcher(ItemStack stack, boolean checkNBT) {
		return new CorporeaItemStackMatcher(stack, checkNBT);
	}

	@Override
	public CorporeaRequestMatcher createMatcher(String name) {
		return new CorporeaStringMatcher(name);
	}

	@Override
	public CorporeaResult requestItem(CorporeaRequestMatcher matcher, int itemCount, CorporeaSpark spark, @Nullable LivingEntity entity, boolean doit) {
		List<ItemStack> stacks = new ArrayList<>();
		if (XplatAbstractions.INSTANCE.fireCorporeaRequestEvent(matcher, itemCount, spark, !doit)) {
			return new CorporeaResultImpl(stacks, 0, 0, Object2IntMaps.emptyMap());
		}

		Object2IntMap<CorporeaNode> matchCountByNode = new Object2IntOpenHashMap<>();
		Set<CorporeaNode> nodes = getNodesOnNetwork(spark);
		Map<CorporeaInterceptor, CorporeaSpark> interceptors = new HashMap<>();

		CorporeaRequest request = new CorporeaRequestImpl(matcher, itemCount, entity);
		for (CorporeaNode node : nodes) {
			CorporeaSpark invSpark = node.getSpark();

			if (node.getWorld().getBlockEntity(node.getPos()) instanceof CorporeaInterceptor interceptor) {
				interceptor.interceptRequest(matcher, itemCount, invSpark, spark, stacks, nodes, doit);
				interceptors.put(interceptor, invSpark);
			}

			var nodeStacks = doit ? node.extractItems(request) : node.countItems(request);
			int sum = 0;
			for (var stack : nodeStacks) {
				sum += stack.getCount();
			}
			matchCountByNode.mergeInt(node, sum, Integer::sum);
			stacks.addAll(nodeStacks);
		}

		for (CorporeaInterceptor interceptor : interceptors.keySet()) {
			interceptor.interceptRequestLast(matcher, itemCount, interceptors.get(interceptor), spark, stacks, nodes, doit);
		}

		return new CorporeaResultImpl(stacks, request.getFound(), request.getExtracted(), matchCountByNode);
	}

	@Override
	public CorporeaSpark getSparkForBlock(Level world, BlockPos pos) {
		List<Entity> sparks = world.getEntitiesOfClass(Entity.class, new AABB(pos.above(), pos.offset(1, 2, 1)), Predicates.instanceOf(CorporeaSpark.class));
		return sparks.isEmpty() ? null : (CorporeaSpark) sparks.get(0);
	}

	@Override
	public int signalStrengthForRequestSize(int requestSize) {
		if (requestSize <= 0) {
			return 0;
		} else if (requestSize >= 16384) {
			return 15;
		} else {
			return Math.min(15, Mth.log2(requestSize) + 1);
		}
	}

	@Override
	public <T extends CorporeaRequestMatcher> void registerRequestMatcher(ResourceLocation id, Class<T> clazz, Function<CompoundTag, T> deserializer) {
		CorporeaRetainerBlockEntity.addCorporeaRequestMatcher(id, clazz, deserializer);
	}

	public void clearCache() {
		cachedNetworks.clear();
	}
}

@Override
public boolean hasInventory(Level level, BlockPos pos, Direction sideOfPos) {
	var state = level.getBlockState(pos);
	var be = level.getBlockEntity(pos);
	return be != null && be.getCapability(ForgeCapabilities.ITEM_HANDLER, sideOfPos).isPresent()
			|| state.getBlock() instanceof WorldlyContainerHolder wch
					&& wch.getContainer(state, level, pos).getSlotsForFace(sideOfPos).length > 0;
}

@Override
public ItemStack insertToInventory(Level level, BlockPos pos, Direction sideOfPos, ItemStack toInsert, boolean simulate) {
	var be = level.getBlockEntity(pos);
	var state = level.getBlockState(pos);
	LazyOptional<IItemHandler> cap = LazyOptional.empty();
	if (be != null) {
		cap = be.getCapability(ForgeCapabilities.ITEM_HANDLER, sideOfPos);
	} else {
		// check vanilla interface for blocks not covered by forge capabilities, e.g. composter
		if (state.getBlock() instanceof WorldlyContainerHolder wch) {
			cap = LazyOptional.of(() -> new SidedInvWrapper(wch.getContainer(state, level, pos), sideOfPos));
		}
	}

	// can't do incremental simulations
	if (simulate || !state.is(BotaniaTags.Blocks.SINGLE_ITEM_INSERT)) {
		return cap.map(handler -> ItemHandlerHelper.insertItemStacked(handler, toInsert, simulate))
				.orElse(toInsert);
	}

	int maxInserts = toInsert.getCount();
	for (int i = 0; i < maxInserts; i++) {
		ItemStack single = toInsert.copyWithCount(1);
		if (!cap.map(handler -> ItemHandlerHelper.insertItemStacked(handler, single, false))
				.orElse(single).isEmpty()) {
			break;
		}
		toInsert.setCount(toInsert.getCount() - 1);
	}
	return toInsert;
}

@Override
public boolean hasInventory(Level level, BlockPos pos, Direction sideOfPos) {
	return ItemStorage.SIDED.find(level, pos, sideOfPos) != null;
}

@Override
public ItemStack insertToInventory(Level level, BlockPos pos, Direction sideOfPos, ItemStack toInsert, boolean simulate) {
	if (toInsert.isEmpty()) {
		//It is valid for Storage#insert implementations to crash when provided empty variants
		return toInsert;
	}

	var state = level.getBlockState(pos);
	var storage = ItemStorage.SIDED.find(level, pos, state, null, sideOfPos);
	if (storage == null) {
		return toInsert;
	}

	var itemVariant = ItemVariant.of(toInsert);
	try (Transaction txn = Transaction.openOuter()) {
		// Truncation to int ok since the value passed in was an int
		// and that value should only decrease or stay same
		int inserted;
		if (state.is(BotaniaTags.Blocks.SINGLE_ITEM_INSERT)) {
			int alreadyInserted = 0;
			for (int i = 0; i < toInsert.getCount(); i++) {
				alreadyInserted += (int) storage.insert(itemVariant, 1L, txn);
			}
			inserted = alreadyInserted;
		} else {
			inserted = (int) storage.insert(itemVariant, toInsert.getCount(), txn);
		}
		if (!simulate) {
			txn.commit();
		}

		if (inserted == toInsert.getCount()) {
			return ItemStack.EMPTY;
		} else {
			var ret = toInsert.copy();
			ret.setCount(toInsert.getCount() - inserted);
			return ret;
		}
	}
}

package vazkii.botania.forge.integration.corporea;

import com.google.common.collect.ImmutableList;

import net.minecraft.core.BlockPos;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraftforge.items.IItemHandler;

import vazkii.botania.api.corporea.CorporeaRequest;
import vazkii.botania.api.corporea.CorporeaSpark;
import vazkii.botania.common.impl.corporea.AbstractCorporeaNode;

import java.util.List;

public class ForgeCapCorporeaNode extends AbstractCorporeaNode {
	protected final IItemHandler inv;

	public ForgeCapCorporeaNode(Level world, BlockPos pos, IItemHandler inv, CorporeaSpark spark) {
		super(world, pos, spark);
		this.inv = inv;
	}

	@Override
	public List<ItemStack> countItems(CorporeaRequest request) {
		return iterateOverSlots(request, false);
	}

	@Override
	public List<ItemStack> extractItems(CorporeaRequest request) {
		return iterateOverSlots(request, true);
	}

	protected List<ItemStack> iterateOverSlots(CorporeaRequest request, boolean doit) {
		ImmutableList.Builder<ItemStack> builder = ImmutableList.builder();

		for (int i = inv.getSlots() - 1; i >= 0; i--) {
			ItemStack stackAt = inv.getStackInSlot(i);
			if (request.getMatcher().test(stackAt)) {
				request.trackFound(stackAt.getCount());

				int rem = Math.min(stackAt.getCount(), request.getStillNeeded() == -1 ? stackAt.getCount() : request.getStillNeeded());
				if (rem > 0) {
					request.trackSatisfied(rem);

					if (doit) {
						ItemStack copy = stackAt.copy();
						builder.addAll(breakDownBigStack(inv.extractItem(i, rem, getSpark().isCreative())));
						getSpark().onItemExtracted(copy);
						request.trackExtracted(rem);
					} else {
						builder.add(inv.extractItem(i, rem, true));
					}
				}
			}
		}

		return builder.build();
	}

}

